const num = (v) => {
  if (v === undefined || v === null || v === "") return null;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ""));
  return isNaN(n) ? null : n;
};
const emailRe = /.+@.+\..+/;
const valid = [];
for (const it of $input.all()) {
  const j = it.json;
  const id = j.Student_ID;
  const name = j.Name;
  const email = (j.Email || "").toString().trim();
  const attendance = num(j.Attendance);
  const gpa = num(j.GPA);
  if (!id || !name || attendance === null || gpa === null) continue;
  valid.push({ json: {
    Student_ID: id,
    Name: name,
    Email: email,
    has_email: emailRe.test(email),
    Attendance: attendance,
    GPA: gpa,
    Math_Midterm: num(j.Math_Midterm),
    DS_Midterm: num(j.DS_Midterm),
    AI_Midterm: num(j.AI_Midterm),
    Credits_Completed: num(j.Credits_Completed),
    Course_Difficulty: j.Course_Difficulty || "",
  } });
}
return valid;

// Deterministic academic-risk scoring (no AI / no external calls).
const j = $json;
const num = (v) => {
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
};

const attendance = num(j.Attendance);
const gpa = num(j.GPA);
const math = num(j.Math_Midterm);
const ds = num(j.DS_Midterm);
const ai = num(j.AI_Midterm);
const credits = num(j.Credits_Completed);
const difficulty = (j.Course_Difficulty || "").toString();

const avgMidterm = Math.round(((math + ds + ai) / 3) * 100) / 100;

let score = 0;
const factors = [];

// Attendance
if (attendance < 60) { score += 30; factors.push("Very low attendance (" + attendance + "%) — below 60%"); }
else if (attendance < 75) { score += 15; factors.push("Low attendance (" + attendance + "%) — between 60% and 74%"); }

// GPA
if (gpa < 5.0) { score += 30; factors.push("Low GPA (" + gpa + ") — below 5.0"); }
else if (gpa < 6.5) { score += 15; factors.push("Moderate GPA (" + gpa + ") — between 5.0 and 6.49"); }

// Average midterm
if (avgMidterm < 40) { score += 25; factors.push("Very low average midterm score (" + avgMidterm + ") — below 40"); }
else if (avgMidterm < 55) { score += 10; factors.push("Below-average midterm score (" + avgMidterm + ") — between 40 and 54"); }

// Credits completed
if (credits < 15) { score += 15; factors.push("Few credits completed (" + credits + ") — below 15"); }

// Course difficulty
if (difficulty.toLowerCase() === "high") { score += 5; factors.push("Enrolled in high-difficulty courses"); }

let level = "Low";
if (score >= 50) level = "High";
else if (score >= 25) level = "Medium";

// Weak subjects (midterm below 55)
const weak = [];
if (math < 55) weak.push("Math");
if (ds < 55) weak.push("Data Science");
if (ai < 55) weak.push("AI");

if (factors.length === 0) factors.push("No significant academic risk factors identified");

return { json: {
  ...j,
  Average_Midterm: avgMidterm,
  Risk_Score: score,
  Risk_Level: level,
  Risk_Factors: factors,
  Weak_Subjects: weak,
} };

const j = $json;
const join = (v) => Array.isArray(v) ? v.join(", ") : (v || "");
return { json: {
  Student_ID: j.Student_ID,
  Name: j.Name,
  Email: j.Email,
  Risk_Score: j.Risk_Score,
  Risk_Level: j.Risk_Level,
  Main_Concerns: join(j.Risk_Factors),
  Weak_Subjects: join(j.Weak_Subjects),
  Recommendations: "",
  Intervention: "No intervention required (low risk).",
  Assessed_At: new Date().toISOString(),
} };

// Deterministic, personalized mentoring plan (no AI / no external calls).
const j = $json;
const name = j.Name;
const level = j.Risk_Level;
const weak = Array.isArray(j.Weak_Subjects) ? j.Weak_Subjects : [];
const attendance = Number(j.Attendance);
const gpa = Number(j.GPA);
const avg = Number(j.Average_Midterm);
const credits = Number(j.Credits_Completed);

const recs = [];
if (attendance < 75) recs.push("Improve attendance — aim to attend every class; current attendance is " + attendance + "%.");
if (gpa < 6.5) recs.push("Meet your academic advisor to build a plan to raise your GPA (currently " + gpa + ").");
weak.forEach((s) => recs.push("Attend tutoring and office hours for " + s + " to strengthen your understanding."));
if (avg < 55) recs.push("Adopt a structured weekly revision schedule and practice past papers to lift midterm performance (average is " + avg + ").");
if (credits < 15) recs.push("Discuss your credit load and progression plan with your advisor (only " + credits + " credits completed).");
if (recs.length === 0) recs.push("Keep up your current study habits and stay consistent.");

const intervention = level === "High"
  ? "Enroll the student in the intensive academic support programme with weekly advisor check-ins and mandatory tutoring for the identified weak subjects."
  : (level === "Medium"
    ? "Schedule bi-weekly advisor check-ins and recommend tutoring for the identified weak subjects."
    : "No formal intervention required; provide standard encouragement and resources.");

const studyPlan = weak.length
  ? "Week 1-2: focus on fundamentals in " + weak.join(", ") + ". Week 3-4: practice problem sets and review midterm mistakes. Ongoing: weekly revision and attend all classes."
  : "Maintain a steady weekly revision routine and continue attending all classes.";

const encouragement = "You have completed " + credits + " credits, " + name + " — with focused, consistent effort on the areas above you can get back on track. Small steps each week make a big difference.";

return { json: {
  ...j,
  Recommendations: recs,
  Intervention: intervention,
  Study_Plan: studyPlan,
  Encouragement: encouragement,
} };

const j = $json;
const join = (v) => Array.isArray(v) ? v.join(", ") : (v || "");
return { json: {
  Student_ID: j.Student_ID,
  Name: j.Name,
  Email: j.Email,
  Risk_Score: j.Risk_Score,
  Risk_Level: j.Risk_Level,
